from contextlib import contextmanager

class Manager:
    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        return False

@contextmanager
def manager():
    with Manager():
        yield

class MarkerError(Exception):
    pass

def check_exit():
    cm = manager()
    cm.__enter__()
    try:
        raise MarkerError("boom")
    except MarkerError as exc:
        return cm.__exit__(type(exc), exc, exc.__traceback__)

